function questionsFor(file) {
  const q = applySetup(inferQuestionnaire(inspectDocx(readFileSync(new URL(`../samples/${file}`, import.meta.url)))), setupFor(file.replace(/\.docx$/, '')));
  const kind = (f) => (f.role === 'condition' && f.type === 'checkbox' ? 'Yes / no' : f.type === 'computed' ? 'Calculated for you' : FIELD_TYPES[f.type].label);
  const label = Object.fromEntries(q.fields.map((f) => [f.key, f.label]));
  return q.fields.map((f) => ({ label: f.label, kind: kind(f), when: f.showIf, whenText: f.showIf && readableCondition(f.showIf, label), children: (f.children || []).map((c) => c.label), computed: f.type === 'computed' }));
}
// "the next one starts with ...": what a second draft of this template fills in by itself (app/lib/prefill.js)
function reuseFor(slug) {
  const r = (setupFor(slug) || {}).reuse;
  if (!r) return '';
  const parts = [];
  if ((r.remember || []).length) parts.push('your own details');
  if ((r.sequence || []).length) parts.push('the next number');
  if ((r.today || []).length) parts.push("today's date");
  return parts.length ? `the next one you make starts with ${andList(parts)} already filled in, so only what is new needs typing.` : '';
}
// "Amount, Subtotal, Tax and Total": what the app works out for the visitor on a template with a ready-made setup
function calculatedFor(slug) {
  const s = setupFor(slug);
  if (!s) return '';
  const names = [];
  for (const o of Object.values(s.fields || {})) {
    if (o.type === 'computed') names.push(o.label);
    for (const c of Object.values(o.children || {})) if (c.type === 'computed') { const l = c.label.toLowerCase(); names.push((l.startsWith('line ') ? l : 'line ' + l) + 's'); }   // a row's amount is each line's
  }
  return [...new Set(names)];
}
const andList = (xs) => (xs.length < 2 ? xs.join('') : xs.slice(0, -1).join(', ') + ' and ' + xs.at(-1));
// "not is_paid and has_stipend" -> 'If "Is paid" is no and "Has stipend" is yes', so readers see the questions, not tag names.
// Anything that is not a plain and/or chain of yes/no questions (brackets, comparisons) returns null and is shown as code.
function readableCondition(expr, label) {
  const joins = expr.match(/\s(and|or)\s/g) || [];
  const terms = expr.split(/\s+(?:and|or)\s+/).map((t) => t.match(/^(not\s+)?([a-z_][a-z0-9_]*)$/));
  if (terms.some((m) => !m || !label[m[2]])) return null;
  return 'If ' + terms.map((m, i) => `${i ? `${joins[i - 1].trim()} ` : ''}“${label[m[2]]}” is ${m[1] ? 'no' : 'yes'}`).join(' ');
}
// One plain sentence for a template card: the first sentence of its intro, cut at a word boundary if it runs long.
const cardLine = (t) => { const s = t.intro.split(/(?<=\.)\s/)[0]; return s.length <= 100 ? s : s.slice(0, s.lastIndexOf(' ', 97)).replace(/[,;:]$/, '') + '…'; };

const faqLd = (faq) => `<script type="application/ld+json">${JSON.stringify({ '@context': 'https://schema.org', '@type': 'FAQPage', mainEntity: faq.map(([q, a]) => ({ '@type': 'Question', name: q, acceptedAnswer: { '@type': 'Answer', text: a } })) })}</script>`;
// The template itself as a document entity: what it is, its format, that it is free, and when its page last changed.
const docLd = (t) => `<script type="application/ld+json">${JSON.stringify({ '@context': 'https://schema.org', '@type': 'DigitalDocument', name: t.title, description: t.intro, url: `${SITE}templates/${t.slug}.html`, encodingFormat: 'application/vnd.openxmlformats-officedocument.wordprocessingml.document', contentUrl: `${SITE}samples/${t.file}`, isAccessibleForFree: true, inLanguage: 'en', genre: t.category, dateModified: LASTMOD, image: [`${SITE}assets/previews/${t.slug}.jpg`, `${SITE}assets/og/${t.slug}.png`], thumbnailUrl: `${SITE}assets/previews/${t.slug}.jpg`, publisher: { '@type': 'Organization', name: 'Clausery', url: SITE } })}</script>`;
// The first-page image beside the list of contents (stacked on phones). Kept out of PREVIEW_CSS so page-only styling
// never invalidates the rendered previews.
