const packSize = () => { const f = new URL(`../samples/${PACK_FILE}`, import.meta.url); return existsSync(f) ? `${Math.round(statSync(f).size / 1024)} KB` : ''; };
const catId = (c) => c.toLowerCase().replace(/\s+/g, '-');
